head.b:skin:
/*
-----------------------------------------------
  Theme Designer variables
  Colours here are editable in Theme > Customise > Advanced.
-----------------------------------------------

<Group description="Brand Colours" selector="body">

  <Variable name="keycolor" description="Accent (teal)" type="color" default="#0F5C56" value="#0F5C56"/>
  <Variable name="tealDeep" description="Accent dark" type="color" default="#0B4640" value="#0B4640"/>
  <Variable name="gold" description="Gold" type="color" default="#B08D45" value="#B08D45"/>
  <Variable name="goldSoft" description="Gold light" type="color" default="#D9C08A" value="#D9C08A"/>
  <Variable name="ink" description="Ink (dark bg / text)" type="color" default="#12233B" value="#12233B"/>
  <Variable name="inkSoft" description="Ink soft" type="color" default="#1F3654" value="#1F3654"/>
  <Variable name="paper" description="Paper (page bg)" type="color" default="#D4D4D1" value="#D4D4D1"/>
  <Variable name="paperDim" description="Paper dim" type="color" default="#C2C2BE" value="#C2C2BE"/>
  <Variable name="slate" description="Slate (muted text)" type="color" default="#5B6472" value="#5B6472"/>
  <Variable name="white" description="Off-white" type="color" default="#DCDCD9" value="#DCDCD9"/>

</Group>

<Variable name="bodyFont" description="Body font stack" type="string" value="'IBM Plex Sans', sans-serif"/>
<Variable name="displayFont" description="Display font stack" type="string" value="'Fraunces', serif"/>
<Variable name="monoFont" description="Mono font stack" type="string" value="'IBM Plex Mono', monospace"/>

-----------------------------------------------
*/

:root{
  --ink:$(ink);
  --ink-soft:$(inkSoft);
  --paper:$(paper);
  --paper-dim:$(paperDim);
  --teal:$(keycolor);
  --teal-deep:$(tealDeep);
  --gold:$(gold);
  --gold-soft:$(goldSoft);
  --slate:$(slate);
  --white:$(white);
  --line:rgba(18,35,59,0.16);

  --display:$(displayFont);
  --body:$(bodyFont);
  --mono:$(monoFont);
}

*{box-sizing:border-box; margin:0; padding:0;}
html{scroll-behavior:smooth;}
body{
  font-family:var(--body);
  color:var(--ink);
  background:var(--paper);
  line-height:1.55;
  -webkit-font-smoothing:antialiased;
}
img{max-width:100%; display:block;}
a{color:inherit; text-decoration:none;}
ul{list-style:none;}
.wrap{max-width:1180px; margin:0 auto; padding:0 28px;}

@media (prefers-reduced-motion: reduce){
  *{animation-duration:0.001ms !important; animation-iteration-count:1 !important; transition-duration:0.001ms !important;}
}

/* Blogger chrome we do not want */
#navbar, .navbar{display:none !important;}

/* ---------- Top bar ---------- */
.topbar{
  background:var(--ink);
  color:var(--paper-dim);
  font-family:var(--mono);
  font-size:12.5px;
  letter-spacing:0.02em;
}
.topbar .wrap{
  display:flex; justify-content:space-between; align-items:center;
  padding-top:9px; padding-bottom:9px; flex-wrap:wrap; gap:6px;
}
.topbar a{opacity:0.85; transition:opacity .15s;}
.topbar a:hover{opacity:1;}
.topbar .locs span{margin-right:18px;}
.topbar .locs span:last-child{margin-right:0;}

/* ---------- Nav ---------- */
header.nav{
  background:var(--paper);
  border-bottom:1px solid var(--line);
  position:sticky; top:0; z-index:50;
}
header.nav .wrap{
  display:flex; align-items:center; justify-content:space-between;
  padding-top:18px; padding-bottom:18px;
}
.brand{
  display:flex; align-items:center; gap:10px;
  font-family:var(--display);
  font-size:22px; font-weight:600; letter-spacing:0.01em;
}
.brand .mark{width:34px; height:34px; flex:none;}
.navlinks{display:flex; gap:34px; align-items:center;}
.navlinks a{
  font-size:14.5px; font-weight:500; color:var(--ink-soft);
  position:relative; padding:4px 0;
}
.navlinks a::after{
  content:''; position:absolute; left:0; bottom:-2px; height:1.5px; width:0;
  background:var(--teal); transition:width .2s ease;
}
.navlinks a:hover::after{width:100%;}
.nav-cta{
  background:var(--teal); color:var(--white); font-weight:600; font-size:14px;
  padding:11px 20px; border-radius:2px; border:1px solid var(--teal);
  transition:background .15s, color .15s;
}
.nav-cta:hover{background:var(--teal-deep); border-color:var(--teal-deep);}

/* ---------- Hero ---------- */
.hero{
  background:var(--ink);
  color:var(--paper);
  position:relative;
  overflow:hidden;
}
.hero .wrap{
  display:grid; grid-template-columns:1.15fr 0.85fr; gap:40px; align-items:center;
  padding-top:96px; padding-bottom:96px;
}
.eyebrow{
  font-family:var(--mono); font-size:12.5px; letter-spacing:0.14em; text-transform:uppercase;
  color:var(--gold-soft); margin-bottom:22px; display:flex; align-items:center; gap:10px;
}
.eyebrow::before{content:''; width:26px; height:1px; background:var(--gold-soft); display:inline-block;}
h1{
  font-family:var(--display); font-weight:600; font-size:clamp(38px, 4.6vw, 60px);
  line-height:1.06; letter-spacing:-0.01em; margin-bottom:24px;
}
h1 em{font-style:italic; color:var(--gold-soft); font-weight:500;}
.hero p.lede{font-size:17.5px; color:#CBD5E1; max-width:46ch; margin-bottom:34px;}
.hero-ctas{display:flex; gap:14px; flex-wrap:wrap; align-items:center;}
.btn-primary{
  background:var(--gold); color:var(--ink); font-weight:700; font-size:15px;
  padding:14px 26px; border-radius:2px; transition:background .15s, transform .15s;
  display:inline-flex; align-items:center; gap:8px;
}
.btn-primary:hover{background:var(--gold-soft); transform:translateY(-1px);}
.btn-ghost{
  color:var(--paper); font-weight:600; font-size:15px; padding:14px 8px;
  border-bottom:1px solid rgba(251,249,244,0.35);
  transition:border-color .15s;
}
.btn-ghost:hover{border-color:var(--paper);}

.stamp-wrap{display:flex; justify-content:center; align-items:center; position:relative;}
.stamp{
  width:280px; height:280px; transform:rotate(-8deg);
  filter:drop-shadow(0 18px 30px rgba(0,0,0,0.35));
}

.hero-stats{
  border-top:1px solid rgba(251,249,244,0.14);
  background:var(--ink-soft);
}
.hero-stats .wrap{
  display:grid; grid-template-columns:repeat(4,1fr);
  padding-top:26px; padding-bottom:26px;
}
.hero-stats .stat{border-right:1px solid rgba(251,249,244,0.14); padding:0 22px;}
.hero-stats .stat:last-child{border-right:none;}
.hero-stats .num{font-family:var(--display); font-size:26px; font-weight:600; color:var(--gold-soft);}
.hero-stats .lbl{font-family:var(--mono); font-size:11.5px; color:#AEB9C7; letter-spacing:0.04em; margin-top:4px;}

/* ---------- Section scaffolding ---------- */
section{padding-top:88px; padding-bottom:88px;}
.section-head{max-width:640px; margin-bottom:52px;}
.section-head .eyebrow{color:var(--gold); margin-bottom:14px;}
.section-head .eyebrow::before{background:var(--gold);}
.section-head h2{
  font-family:var(--display); font-size:clamp(28px,3vw,38px); font-weight:600;
  letter-spacing:-0.01em; color:var(--ink);
}
.section-head p{color:var(--slate); margin-top:14px; font-size:16px; max-width:56ch;}

/* ---------- About ---------- */
.about{background:var(--paper);}
.about .wrap{display:grid; grid-template-columns:0.9fr 1.1fr; gap:60px; align-items:start;}
.about-figure{
  background:var(--paper-dim); border:1px solid var(--line); padding:32px;
  font-family:var(--mono); font-size:13px; color:var(--slate);
}
.about-figure .big{font-family:var(--display); font-size:52px; font-weight:600; color:var(--teal); line-height:1;}
.about-figure .row{display:flex; justify-content:space-between; padding:14px 0; border-top:1px solid var(--line);}
.about-figure .row:first-of-type{border-top:none; padding-top:0;}
.about p{color:var(--ink-soft); font-size:16px; margin-bottom:18px; max-width:60ch;}

/* ---------- Services grid ---------- */
.services{background:var(--paper-dim);}
.service-grid{
  display:grid; grid-template-columns:repeat(3,1fr); gap:1px;
  background:var(--line); border:1px solid var(--line);
}
.service-card{
  background:var(--paper); padding:30px 26px; min-height:190px;
  display:flex; flex-direction:column; justify-content:space-between;
  transition:background .18s; color:inherit; text-decoration:none;
}
.service-card:hover{background:var(--white);}
.service-card .idx{font-family:var(--mono); font-size:12px; color:var(--gold); letter-spacing:0.05em;}
.service-card h3{font-family:var(--display); font-weight:600; font-size:19px; margin-top:16px; margin-bottom:8px;}
.service-card p{font-size:13.5px; color:var(--slate); margin-bottom:16px;}
.service-card .go{font-size:13px; font-weight:600; color:var(--teal); display:inline-flex; align-items:center; gap:6px;}
.service-card .go svg{transition:transform .15s;}
.service-card:hover .go svg{transform:translateX(3px);}

/* ---------- Process ---------- */
.process{background:var(--ink); color:var(--paper);}
.process .section-head h2{color:var(--paper);}
.process .section-head p{color:#AEB9C7;}
.process .section-head .eyebrow{color:var(--gold-soft);}
.process .section-head .eyebrow::before{background:var(--gold-soft);}
.timeline{border-left:1px solid rgba(251,249,244,0.18); margin-left:8px;}
.tl-step{position:relative; padding:0 0 44px 36px;}
.tl-step:last-child{padding-bottom:0;}
.tl-step::before{
  content:attr(data-n); position:absolute; left:-19px; top:0;
  width:37px; height:37px; border-radius:50%; background:var(--ink);
  border:1px solid var(--gold-soft); color:var(--gold-soft);
  font-family:var(--mono); font-size:13px; display:flex; align-items:center; justify-content:center;
}
.tl-step h4{font-family:var(--display); font-weight:600; font-size:19px; margin-bottom:8px;}
.tl-step p{color:#C6CFDA; font-size:14.5px; max-width:60ch;}

/* ---------- Documents ---------- */
.docs{background:var(--paper);}
.doc-tabs{display:flex; gap:8px; margin-bottom:0; border-bottom:1px solid var(--line);}
.doc-tab{
  font-family:var(--mono); font-size:13px; padding:12px 20px; color:var(--slate);
  border-bottom:2px solid transparent; cursor:pointer; background:none;
  border-top:none; border-left:none; border-right:none;
}
.doc-tab.active{color:var(--teal); border-bottom-color:var(--teal); font-weight:600;}
.doc-panel{display:none; padding-top:30px;}
.doc-panel.active{display:grid; grid-template-columns:repeat(2,1fr); gap:12px 40px;}
.doc-panel li{
  font-size:15px; color:var(--ink-soft); padding:10px 0; border-bottom:1px dashed var(--line);
  display:flex; gap:10px; align-items:baseline;
}
.doc-panel li::before{content:'—'; color:var(--gold); flex:none;}

/* ---------- Reviews ---------- */
.reviews{background:var(--paper-dim);}
.review-row{display:grid; grid-template-columns:repeat(3,1fr); gap:24px;}
.review-card{background:var(--paper); border:1px solid var(--line); padding:28px;}
.review-card .quote{font-family:var(--display); font-size:16.5px; line-height:1.5; color:var(--ink); margin-bottom:20px;}
.review-card .who{font-family:var(--mono); font-size:12.5px; color:var(--slate);}

/* ---------- CTA band ---------- */
.cta-band{background:var(--teal); color:var(--white);}
.cta-band .wrap{
  display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:24px;
  padding-top:52px; padding-bottom:52px;
}
.cta-band h3{font-family:var(--display); font-size:26px; font-weight:600; max-width:36ch;}
.cta-band .btn-primary{background:var(--white); color:var(--teal-deep);}
.cta-band .btn-primary:hover{background:var(--paper-dim);}

/* ---------- Footer ---------- */
footer{background:var(--ink); color:#AEB9C7; font-size:14px;}
footer .wrap{padding-top:64px; padding-bottom:36px;}
.foot-grid{display:grid; grid-template-columns:1.3fr 1fr 1fr 1fr; gap:40px; padding-bottom:40px;}
.foot-col h5{
  font-family:var(--mono); font-size:12px; letter-spacing:0.08em; text-transform:uppercase;
  color:var(--gold-soft); margin-bottom:16px;
}
.foot-col p, .foot-col li{margin-bottom:9px; color:#AEB9C7;}
.foot-col a:hover{color:var(--paper);}
.foot-brand{font-family:var(--display); font-size:20px; color:var(--paper); font-weight:600; margin-bottom:12px;}
.foot-bottom{
  border-top:1px solid rgba(251,249,244,0.12); padding-top:22px;
  display:flex; justify-content:space-between; flex-wrap:wrap; gap:10px; font-size:12.5px; color:#8695A6;
}

/* =========================================================
   Static page styles
   (page-hero, services detail, about values, contact)
   ========================================================= */
.page-hero{background:var(--ink); color:var(--paper); padding-top:64px; padding-bottom:64px;}
.page-hero h1{font-family:var(--display); font-weight:600; font-size:clamp(32px,4vw,46px); letter-spacing:-0.01em;}
.page-hero .crumb{
  font-family:var(--mono); font-size:12.5px; color:var(--gold-soft);
  letter-spacing:0.1em; text-transform:uppercase; margin-bottom:16px;
}

/* About page */
.value-grid{
  display:grid; grid-template-columns:repeat(3,1fr); gap:1px; background:var(--line);
  border:1px solid var(--line); margin-top:40px;
}
.value-card{background:var(--paper); padding:28px;}
.value-card h4{font-family:var(--display); font-size:18px; font-weight:600; margin-bottom:10px; color:var(--teal);}
.value-card p{font-size:14.5px; color:var(--slate);}

/* Services page */
.svc-nav{
  position:sticky; top:73px; background:var(--paper-dim); border-bottom:1px solid var(--line);
  overflow-x:auto; z-index:40;
}
.svc-nav .wrap{display:flex; gap:4px; padding-top:0; padding-bottom:0; white-space:nowrap;}
.svc-nav a{
  font-family:var(--mono); font-size:12.5px; padding:14px 16px; color:var(--slate);
  border-bottom:2px solid transparent;
}
.svc-nav a:hover{color:var(--teal); border-bottom-color:var(--teal);}
.svc-block{padding-top:64px; padding-bottom:64px; border-bottom:1px solid var(--line); scroll-margin-top:130px;}
/* Explicit .alt instead of :nth-child(even) — Blogger may re-wrap page content. */
.svc-block.alt{background:var(--paper-dim);}
.svc-block .wrap{display:grid; grid-template-columns:1fr 1fr; gap:56px; align-items:start;}
.svc-block .idx{font-family:var(--mono); font-size:13px; color:var(--gold); letter-spacing:0.05em; margin-bottom:14px;}
.svc-block h2{font-family:var(--display); font-size:28px; font-weight:600; margin-bottom:16px;}
.svc-block p{color:var(--slate); font-size:15.5px; margin-bottom:14px;}
.svc-block h4{font-family:var(--mono); font-size:12px; text-transform:uppercase; letter-spacing:0.06em; color:var(--teal); margin-bottom:12px;}
.svc-block ul{border-top:1px solid var(--line);}
.svc-block li{
  font-size:14.5px; color:var(--ink-soft); padding:10px 0; border-bottom:1px dashed var(--line);
  display:flex; gap:10px; align-items:baseline;
}
.svc-block li::before{content:'—'; color:var(--gold); flex:none;}

/* Contact page */
.contact-grid{display:grid; grid-template-columns:1fr 1fr; gap:56px; align-items:start;}
.info-card{background:var(--paper-dim); border:1px solid var(--line); padding:30px;}
.info-card h4{
  font-family:var(--mono); font-size:12px; text-transform:uppercase; letter-spacing:0.06em;
  color:var(--teal); margin-bottom:14px;
}
.info-card + .info-card{margin-top:20px;}
/* Contact page shows the info cards as a row; the enquiry form is a gadget below. */
.info-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:24px;}
.info-grid .info-card + .info-card{margin-top:0;}
.info-card p{font-size:15px; color:var(--ink-soft); margin-bottom:6px;}
.info-card a{color:var(--teal); font-weight:600;}
.map-row{display:grid; grid-template-columns:1fr 1fr; gap:24px; margin-top:20px;}
.map-row iframe{width:100%; height:240px; border:1px solid var(--line); filter:grayscale(0.15);}

/* Blog: list ---------- */
.list-head{background:var(--ink); color:var(--paper); padding-top:64px; padding-bottom:64px;}
.list-head .eyebrow{margin-bottom:14px;}
.list-title{font-family:var(--display); font-weight:600; font-size:clamp(30px,4vw,44px); letter-spacing:-0.01em;}
.post-list-section{padding-top:64px; padding-bottom:64px;}
.post-list{display:grid; grid-template-columns:repeat(3,1fr); gap:1px; background:var(--line); border:1px solid var(--line);}
.post-card{
  background:var(--paper); padding:30px 26px; min-height:200px;
  display:flex; flex-direction:column; transition:background .18s;
}
.post-card:hover{background:var(--white);}
.post-card-date{font-family:var(--mono); font-size:12px; color:var(--gold); letter-spacing:0.05em;}
.post-card-title{font-family:var(--display); font-weight:600; font-size:19px; margin:16px 0 8px;}
.post-card-snippet{font-size:13.5px; color:var(--slate); margin-bottom:16px; flex:1;}
.post-card .go{font-size:13px; font-weight:600; color:var(--teal); display:inline-flex; align-items:center; gap:6px;}
.pager{display:flex; justify-content:space-between; gap:16px; margin-top:40px;}
.pager-btn{
  font-family:var(--mono); font-size:13px; color:var(--teal);
  border:1px solid var(--line); padding:12px 20px; background:var(--paper-dim);
}
.pager-btn:hover{background:var(--white);}
.no-posts{font-family:var(--mono); font-size:14px; color:var(--slate); padding:40px 0;}

/* Blog: single post ---------- */
.post-single{padding-top:64px; padding-bottom:64px;}
.post-head{max-width:760px; margin:0 auto 40px;}
.post-head h1{font-size:clamp(30px,4vw,46px); margin-bottom:18px;}
.post-meta{
  display:flex; gap:18px; flex-wrap:wrap;
  font-family:var(--mono); font-size:12.5px; color:var(--slate);
  padding-top:18px; border-top:1px solid var(--line);
}
.post-body{max-width:760px; margin:0 auto; font-size:16.5px; color:var(--ink-soft);}
.post-body p{margin-bottom:20px;}
.post-body h2, .post-body h3{
  font-family:var(--display); font-weight:600; color:var(--ink);
  margin:36px 0 16px; line-height:1.2;
}
.post-body h2{font-size:28px;}
.post-body h3{font-size:22px;}
.post-body a{color:var(--teal); font-weight:600; border-bottom:1px solid var(--line);}
.post-body ul, .post-body ol{margin:0 0 20px 22px;}
.post-body ul{list-style:disc;}
.post-body ol{list-style:decimal;}
.post-body li{margin-bottom:8px;}
.post-body blockquote{
  border-left:3px solid var(--gold); padding:4px 0 4px 22px; margin:0 0 20px;
  font-family:var(--display); font-size:18px; color:var(--ink);
}
.post-body img{margin:24px 0;}
.post-body table{width:100%; border-collapse:collapse; margin-bottom:20px; font-size:15px;}
.post-body th, .post-body td{border:1px solid var(--line); padding:10px 12px; text-align:left;}
.post-labels{max-width:760px; margin:44px auto 0; display:flex; gap:8px; flex-wrap:wrap;}
.post-label{
  font-family:var(--mono); font-size:12px; color:var(--slate);
  border:1px solid var(--line); padding:6px 12px; background:var(--paper-dim);
}
.post-label:hover{color:var(--teal);}

/* Error / 404 ---------- */
.error-page{padding-top:96px; padding-bottom:96px;}
.error-page h1{margin-bottom:18px;}
.error-page p{color:var(--slate); font-size:17px; max-width:52ch; margin-bottom:30px;}

/* Blogger contact form gadget ---------- */
.contact-form-section{background:var(--paper-dim); padding-top:64px; padding-bottom:64px;}
.contact-form-widget{max-width:640px;}
.contact-form-widget .form{display:flex; flex-direction:column; gap:16px;}
.contact-form-widget label{
  font-family:var(--mono); font-size:12px; text-transform:uppercase; letter-spacing:0.05em;
  color:var(--slate); margin-bottom:6px; display:block;
}
.contact-form-widget input[type='text'],
.contact-form-widget input[type='email'],
.contact-form-widget textarea{
  width:100%; font-family:var(--body); font-size:15px; padding:12px 14px;
  border:1px solid var(--line); background:var(--paper); color:var(--ink); border-radius:2px;
}
.contact-form-widget input[type='text']:focus,
.contact-form-widget input[type='email']:focus,
.contact-form-widget textarea:focus{outline:none; border-color:var(--teal);}
.contact-form-widget textarea{min-height:120px; resize:vertical;}
.contact-form-button-submit{
  background:var(--teal); color:var(--white); font-family:var(--body); font-weight:700; font-size:15px;
  padding:14px 26px; border:none; border-radius:2px; cursor:pointer; width:fit-content;
  transition:background .15s;
}
.contact-form-button-submit:hover{background:var(--teal-deep);}
.contact-form-error-message, .contact-form-success-message{
  font-family:var(--mono); font-size:12.5px; color:var(--slate);
}

/* ---------- Responsive ---------- */
@media (max-width:900px){
  .hero .wrap{grid-template-columns:1fr;}
  .stamp-wrap{order:-1;}
  .stamp{width:180px; height:180px;}
  .about .wrap{grid-template-columns:1fr;}
  .hero-stats .wrap{grid-template-columns:repeat(2,1fr); row-gap:20px;}
  .hero-stats .stat:nth-child(2){border-right:none;}
  .navlinks{display:none;}
  .service-grid{grid-template-columns:repeat(2,1fr);}
  .post-list{grid-template-columns:repeat(2,1fr);}
  .review-row{grid-template-columns:1fr;}
}
@media (max-width:850px){
  .contact-grid{grid-template-columns:1fr;}
  .info-grid{grid-template-columns:1fr;}
  .map-row{grid-template-columns:1fr;}
}
@media (max-width:800px){
  .svc-block .wrap{grid-template-columns:1fr;}
  .value-grid{grid-template-columns:1fr;}
  .foot-grid{grid-template-columns:1fr 1fr;}
}
@media (max-width:640px){
  .doc-panel.active{grid-template-columns:1fr;}
}
@media (max-width:560px){
  .service-grid{grid-template-columns:1fr;}
  .post-list{grid-template-columns:1fr;}
}
@media (max-width:520px){
  .foot-grid{grid-template-columns:1fr;}
}

head.b:template-skin:
/* Layout (edit-mode) chrome — keeps Blogger's drag/drop view readable. */
body#layout{background:#eef1f4;}
body#layout .wrap{max-width:none; padding:0 12px;}
body#layout .section{background:#fff; border:1px dashed #b9c2cc; border-radius:3px; margin:10px 0; padding:10px;}
body#layout .section h4{font:600 12px/1.4 sans-serif; color:#12233B; margin:0 0 6px;}
body#layout .layout-widget-description{font:400 10px/1.4 sans-serif; color:#6b7684;}
body#layout .no-items{display:block;}
body#layout #navbar, body#layout .topbar, body#layout header.nav,
body#layout footer, body#layout .hero, body#layout .hero-stats,
body#layout .services, body#layout .process, body#layout .docs,
body#layout .reviews, body#layout .cta-band{display:none;}

body.script:
//
  (function () {
    var tabs = document.querySelectorAll('.doc-tab');
    if (!tabs.length) return;
    Array.prototype.forEach.call(tabs, function (tab) {
      tab.addEventListener('click', function () {
        Array.prototype.forEach.call(document.querySelectorAll('.doc-tab'), function (t) {
          t.classList.remove('active');
        });
        Array.prototype.forEach.call(document.querySelectorAll('.doc-panel'), function (p) {
          p.classList.remove('active');
        });
        tab.classList.add('active');
        var panel = document.getElementById(tab.getAttribute('data-tab'));
        if (panel) panel.classList.add('active');
      });
    });
  })();
//
